    import resource
    resource.setrlimit(resource.RLIMIT_CORE,(0,0));os.umask(0o077)
    need(SESSION.resolve(strict=True)==SESSION and not NEW.exists() and NEW.resolve()==NEW and not OUTPUT.exists() and not OUTPUT.is_symlink(),'Existing outputs preserved; no blind retry')
    evidence=json.loads(read(BASE/'guest-diagnose-v2/return.json'))
    need(evidence.get('firecrackerReaped') is True and evidence.get('allOwnedTraceesReaped') is True and evidence.get('safeToRetireThisLease') is True,'Prior diagnostic child/lease not definitely released')
    records=evidence.get('sigsysDiagnostics');need(isinstance(records,list) and len(records)==1,'Expected one actual captured syscall')
    row=records[0];need(row.get('syscall')==row.get('registerSyscall')==172 and row.get('siCode')==1 and row.get('arch')==3221225655 and row.get('isRootThread') is True and row.get('tid')==row.get('rootPid') and row.get('filterDisabled') is False,'Actual evidence does not authorize this VMM-only getpid rule')
    old_raw=read(SESSION/'diagnose-v2/guest-config.json');need(hashlib.sha256(old_raw).hexdigest()==CONFIG_SHA,'Prior diagnostic config differs')
